CREATE TYPE "SubscriptionStatus" AS ENUM ('PENDING','ACTIVE','PAST_DUE','CANCELLED','EXPIRED','SUSPENDED');
CREATE TYPE "BillingCycle" AS ENUM ('MONTHLY','QUARTERLY','YEARLY');
CREATE TYPE "PaymentPurpose" AS ENUM ('SAAS_SUBSCRIPTION','CONSUMER_PLAN','SERVICE');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','CONFIRMED','FAILED','REFUNDED','CANCELLED');
ALTER TABLE "Barbershop" ADD COLUMN "publicListingApproved" BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN "googlePlaceId" TEXT, ADD COLUMN "googleReviewCount" INTEGER, ADD COLUMN "timezone" TEXT NOT NULL DEFAULT 'America/Sao_Paulo';
CREATE TABLE "SaasPlan" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"price" DECIMAL(10,2) NOT NULL,"cycle" "BillingCycle" NOT NULL DEFAULT 'MONTHLY',"active" BOOLEAN NOT NULL DEFAULT TRUE,"features" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SaasPlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SaasSubscription" ("id" TEXT NOT NULL,"barbershopId" TEXT NOT NULL,"planId" TEXT NOT NULL,"status" "SubscriptionStatus" NOT NULL DEFAULT 'PENDING',"amount" DECIMAL(10,2) NOT NULL,"cycle" "BillingCycle" NOT NULL,"currentPeriodStart" TIMESTAMP(3),"currentPeriodEnd" TIMESTAMP(3),"cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT FALSE,"gateway" TEXT,"gatewayCustomerId" TEXT,"gatewaySubscriptionId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SaasSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConsumerPlan" ("id" TEXT NOT NULL,"barbershopId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"price" DECIMAL(10,2) NOT NULL,"cycle" "BillingCycle" NOT NULL DEFAULT 'MONTHLY',"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConsumerPlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ConsumerPlanService" ("planId" TEXT NOT NULL,"serviceId" TEXT NOT NULL,CONSTRAINT "ConsumerPlanService_pkey" PRIMARY KEY ("planId","serviceId"));
CREATE TABLE "ConsumerSubscription" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"barbershopId" TEXT NOT NULL,"planId" TEXT NOT NULL,"status" "SubscriptionStatus" NOT NULL DEFAULT 'PENDING',"currentPeriodStart" TIMESTAMP(3),"currentPeriodEnd" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ConsumerSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BillingPayment" ("id" TEXT NOT NULL,"purpose" "PaymentPurpose" NOT NULL,"status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"amount" DECIMAL(10,2) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'BRL',"gateway" TEXT,"gatewayPaymentId" TEXT,"idempotencyKey" TEXT,"saasSubscriptionId" TEXT,"consumerSubscriptionId" TEXT,"bookingId" TEXT,"barbershopId" TEXT,"userId" TEXT,"paidAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BillingPayment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GatewayWebhookEvent" ("id" TEXT NOT NULL,"gateway" TEXT NOT NULL,"eventId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"payload" JSONB NOT NULL,"processedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GatewayWebhookEvent_pkey" PRIMARY KEY ("id"));
